const fs = require('fs');
const crypto = require('crypto');
const playwrightRoot = '/Users/samchou/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright';
const { chromium } = require(playwrightRoot);
const cases = [
  {
    id: 'first_legend_and_body',
    html: '<fieldset disabled><legend><input id="legend" required></legend><input id="body" required></fieldset>',
    expected: {
      legend: { ownDisabled: false, effectiveDisabled: false, willValidate: true, checkValidity: false },
      body: { ownDisabled: false, effectiveDisabled: true, willValidate: false, checkValidity: true },
    },
  },
  {
    id: 'inner_legend_does_not_exempt_outer_fieldset',
    html: '<fieldset disabled><legend>Outer</legend><fieldset disabled><legend><input id="nested" required></legend></fieldset></fieldset>',
    expected: { nested: { ownDisabled: false, effectiveDisabled: true, willValidate: false, checkValidity: true } },
  },
  {
    id: 'own_boolean_attribute_inside_legend',
    html: '<fieldset disabled><legend><input id="own" disabled="false" required></legend></fieldset>',
    expected: { own: { ownDisabled: true, effectiveDisabled: true, willValidate: false, checkValidity: true } },
  },
  {
    id: 'barred_does_not_imply_disabled',
    html: '<datalist><input id="listed" required></datalist>',
    expected: { listed: { ownDisabled: false, effectiveDisabled: false, willValidate: false, checkValidity: true } },
  },
];
(async () => {
  const browser = await chromium.launch({ headless: true, chromiumSandbox: true });
  try {
    const context = await browser.newContext({ offline: true, javaScriptEnabled: false, acceptDownloads: false });
    await context.route('**/*', route => route.abort());
    const page = await context.newPage();
    for (const item of cases) {
      await page.setContent(item.html);
      item.actual = await page.evaluate(() => Object.fromEntries([...document.querySelectorAll('input')].map(input => [input.id, {
        ownDisabled: input.disabled,
        effectiveDisabled: input.matches(':disabled'),
        willValidate: input.willValidate,
        checkValidity: input.checkValidity(),
      }])));
      item.serializedDOM = await page.locator('body').innerHTML();
      item.matchesExpected = JSON.stringify(item.actual) === JSON.stringify(item.expected);
    }
    const report = {
      kind: 'Local browser observations for assistant-created source sanity controls; not generated MCQ evaluation',
      date: '2026-09-06', browserVersion: browser.version(),
      playwrightVersion: require(playwrightRoot + '/package.json').version,
      settings: { offline: true, javaScriptEnabled: false, acceptDownloads: false, allRoutesAborted: true },
      source: 'https://html.spec.whatwg.org/multipage/form-control-infrastructure.html',
      cases, runnerSource: fs.readFileSync(__filename, 'utf8'),
      limits: ['Only these exact DOMs and properties were observed.', 'The browser result does not establish correctness of arbitrary question prose, explanations, or learning difficulty.'],
    };
    const path = '/tmp/checkpoint-html-evidence-preflight-20260906.json';
    fs.writeFileSync(path, JSON.stringify(report, null, 2) + '\n');
    console.log(JSON.stringify({ path, sha256: crypto.createHash('sha256').update(fs.readFileSync(path)).digest('hex'), browser: report.browserVersion, results: cases.map(c => ({ id: c.id, matches: c.matchesExpected })) }));
    if (cases.some(c => !c.matchesExpected)) process.exitCode = 1;
  } finally { await browser.close(); }
})().catch(error => { console.error(error.message); process.exitCode = 1; });
